import {
  Provider,
  Text,
  TextContext,
  SelectionIndicator,
  ToggleButton as AriaToggleButton,
  ToggleButtonGroup as AriaToggleButtonGroup,
} from "react-aria-components";
import type {
  ToggleButtonGroupProps as AriaToggleButtonGroupProps,
  ToggleButtonProps as AriaToggleButtonProps,
} from "react-aria-components";
import { Children, createContext, useContext } from "react";
import type { ReactNode, Ref } from "react";
import { Check } from "./icons";
import { roleSize, type ControlSize } from "./controlSize";
import "./SegmentedControl.css";

// SegmentedControl (Component, Category A) — an iOS-style single-select control: a
// track of adjacent segments with a raised "pill" behind the selected one. Behavior
// is borrowed from React Aria ToggleButtonGroup (single selection, roving focus,
// keyboard); the look (inset track + raised selected pill) is owned via Cmp tokens.
// Distinct from ToggleButtonGroup (separate brand-filled toggle buttons).
type SegmentedControlSize = ControlSize;
type SegmentedControlVariant = "filled" | "outline";

// Propagates the SegmentedControl's `size` down to each SegmentedControlItem, so the segment
// text scales with the control (`sd-type-label-${roleSize(size)}`, same as ToggleButton) instead of being
// fixed. Size lives on the group, not the item — context is how the item reads it.
const SegmentedControlSizeContext = createContext<SegmentedControlSize>("medium");
// The variant rides beside it for the same reason: the item draws the leading check.
const SegmentedControlVariantContext = createContext<SegmentedControlVariant>("filled");

export interface SegmentedControlProps
  extends Omit<
    AriaToggleButtonGroupProps,
    "className" | "children" | "selectionMode" | "disallowEmptySelection"
  > {
  /**
   * Visual variant. `filled` is an inset track with a raised pill behind the selected segment;
   * `outline` is a bordered track whose selected segment takes the brand tint and a leading check.
   * A check rather than a radio ring, because ToggleButtonGroup's outline chips use the ring for one
   * selection.
   *
   * @default "filled"
   */
  variant?: SegmentedControlVariant;
  /**
   * Size axis (track/segment height).
   *
   * @default "medium"
   */
  size?: SegmentedControlSize;
  /**
   * Fill the container, the segments sharing its width equally. Off, the track hugs its labels.
   * For a control that spans a panel or a bar, where hugging would leave a ragged end.
   *
   * @default false
   */
  isFullWidth?: boolean;
  /** SegmentedControlItem children. */
  children?: ReactNode;
  /** Additional class. sd-segmented-control is always retained. */
  className?: string;
  /** Passed to the root group DOM element. */
  ref?: Ref<HTMLDivElement>;
}

export interface SegmentedControlItemProps
  extends Omit<AriaToggleButtonProps, "className" | "children"> {
  /** Segment content. */
  children?: ReactNode;
  /** Additional class. sd-segmented-control__segment is always retained. */
  className?: string;
  /** Passed to the underlying button DOM element. */
  ref?: Ref<HTMLButtonElement>;
}

export function SegmentedControl({
  variant = "filled",
  size = "medium",
  isFullWidth = false,
  children,
  className,
  ref,
  ...props
}: SegmentedControlProps) {
  return (
    <AriaToggleButtonGroup
      {...props}
      ref={ref}
      // Both are hard-coded AFTER `{...props}`, so they win over anything a caller passes — and
      // both are Omit-ed from the props type above so a caller cannot pass them at all. That pairing
      // IS the component: a segmented control is one-of-N with no empty state, which is what
      // separates it from ToggleButtonGroup (multi, emptiable) and from Tabs (panels are page
      // structure). Without the Omit a consumer could pass `disallowEmptySelection={false}`, get no
      // type error, and see no effect.
      //
      // @usageInvariant segmented-control-single-selection
      selectionMode="single"
      disallowEmptySelection
      data-variant={variant}
      data-size={size}
      data-full-width={isFullWidth || undefined}
      className={className ? `sd-segmented-control ${className}` : "sd-segmented-control"}
    >
      <SegmentedControlSizeContext.Provider value={size}>
        <SegmentedControlVariantContext.Provider value={variant}>{children}</SegmentedControlVariantContext.Provider>
      </SegmentedControlSizeContext.Provider>
    </AriaToggleButtonGroup>
  );
}

/** Text-only children get the `__text` slot automatically, the rule Button's `isTextOnly` states. */
function isTextOnly(content: ReactNode): boolean {
  const parts = Children.toArray(content);
  return parts.length > 0 && parts.every((p) => typeof p === "string" || typeof p === "number");
}

export function SegmentedControlItem({
  children,
  className,
  ref,
  ...props
}: SegmentedControlItemProps) {
  const size = useContext(SegmentedControlSizeContext);
  const variant = useContext(SegmentedControlVariantContext);
  return (
    <AriaToggleButton
      {...props}
      ref={ref}
      data-variant={variant}
      data-size={size}
      className={
        className
          ? `sd-segmented-control__segment sd-type-label-${roleSize(size)} ${className}`
          : `sd-segmented-control__segment sd-type-label-${roleSize(size)}`
      }
    >
      {/* The label is a real text slot, as on Button, so a squeezed segment can ellipsize: the
          segment is a flex container, and `text-overflow` applies only to a block the text sits in. */}
      {variant === "outline" && (
        // Decorative: React Aria exposes the selection. Reserved at rest (hidden, not removed), so
        // selecting a segment never shifts its label or resizes a hugging track.
        <span aria-hidden="true" data-size={size} className="sd-segmented-control__check">
          <Check size="1em" />
        </span>
      )}
      <Provider values={[[TextContext, { className: "sd-segmented-control__text" }]]}>
        {isTextOnly(children) ? <Text>{children}</Text> : children}
      </Provider>
      {/* The selected segment's pill: React Aria's SelectionIndicator, rendered on the selected
          segment only and sliding from the previous one, under the label and the state wash. */}
      <SelectionIndicator data-variant={variant} className="sd-segmented-control__indicator" />
    </AriaToggleButton>
  );
}

/* SegmentedControl.css — .sd-segmented-control (+ __segment)
   sd- prefix / single flat class / state via react-aria data-* / Cmp tokens only.
   Inset track holding adjacent segments; the selected segment gets a raised pill. */
.sd-segmented-control {
  display: inline-flex;
  align-items: center;
  /* Honour the host instead of bursting it. `inline-flex` + `nowrap` sizes the track to its
     content, so below that width the track would overflow its container and push the page. The answer is
     NOT the one Tabs took — `component-usage.md` scopes this component to "one choice out of a
     few, as a joined track" and hands "too many options to show at once" to `Select`, so a
     scrolling track would be honouring a call the fork already routes elsewhere, and a wrapped
     one breaks the single joined track that IS the component. It contains instead: the track
     stops at its host and the segments below share what there is. */
  max-width: 100%;
  padding: var(--sd-segmented-control-padding);
  background: var(--sd-segmented-control-background);
  /* The `filled` groove is drawn by its fill alone; the edge stays as a transparent width so both
     variants keep one box and the segments sit at the same place in each. `outline` colours it. */
  border: var(--sd-segmented-control-border-width) solid transparent;
}

/* Full width: the track takes its container and the segments split it equally. The root carries
   the attribute and the segments react through a `-current` relay (component-contract.md § 6 rule
   5). `1 1 0` sizes every segment from zero, so a long label cannot widen its own share; the
   segment's `min-width: 0` and the `__text` ellipsis then handle a label that outgrows it. */
/* A track hugs its segments unless `isFullWidth` says otherwise, even inside a parent that stretches
   its children (a column Stack, a grid cell): stretched without the flag, the track ran the full width
   while its segments stayed packed at the start. Full width is the flag's job, and it widens the
   segments with the track. */
.sd-segmented-control {
  --sd-segmented-control-segment-flex-current: 0 1 auto;
  align-self: flex-start;
  justify-self: start;
}
.sd-segmented-control[data-full-width] {
  display: flex;
  width: 100%;
  align-self: stretch;
  justify-self: stretch;
  --sd-segmented-control-segment-flex-current: 1 1 0;
}

/* Radius scales with size (concentric: track R − padding = segment R). */
.sd-segmented-control[data-size="x-small"] {
  height: var(--sd-segmented-control-height-x-small);
  border-radius: var(--sd-segmented-control-radius-x-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control[data-size="small"] {
  height: var(--sd-segmented-control-height-small);
  border-radius: var(--sd-segmented-control-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control[data-size="medium"] {
  height: var(--sd-segmented-control-height-medium);
  border-radius: var(--sd-segmented-control-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control[data-size="large"] {
  height: var(--sd-segmented-control-height-large);
  border-radius: var(--sd-segmented-control-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control[data-size="x-large"] {
  height: var(--sd-segmented-control-height-x-large);
  border-radius: var(--sd-segmented-control-radius-x-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-segmented-control__text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sd-segmented-control__segment {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: var(--sd-segmented-control-segment-flex-current);
  height: 100%;
  padding-inline: var(--sd-segmented-control-segment-padding-inline);
  border: 0;
  background: transparent;
  color: var(--sd-segmented-control-segment-foreground);
  white-space: nowrap;
  /* A flex item refuses to shrink below its content by default (`min-width: auto`), which is what
     made the track burst rather than the segments give — so the track's `max-width` above does
     nothing without this. `overflow: hidden` then keeps a squeezed label inside its own segment
     instead of over its neighbour's pill.
     The ellipsis lives on the `__text` slot above, because `text-overflow` applies to a block
     container and the segment is a flex one: on the segment itself it computes to `ellipsis` and
     the label still hard-clips at BOTH ends. That slot also clips the label, so
     the segment itself does not: it would cut the selection pill as it slides in from a neighbour. */
  min-width: 0;
  cursor: pointer;
  outline: none;
  appearance: none;
  transition:
    color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-segmented-control-segment-state-hover-current: var(--sd-state-hover);
  --sd-segmented-control-segment-state-pressed-current: var(--sd-state-pressed);
}
.sd-segmented-control__segment[data-size="x-small"] {
  border-radius: var(--sd-segmented-control-segment-radius-x-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control__segment[data-size="small"] {
  border-radius: var(--sd-segmented-control-segment-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control__segment[data-size="medium"] {
  border-radius: var(--sd-segmented-control-segment-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control__segment[data-size="large"] {
  border-radius: var(--sd-segmented-control-segment-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-segmented-control__segment[data-size="x-large"] {
  border-radius: var(--sd-segmented-control-segment-radius-x-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* Hover/pressed state-layer overlay. React Aria emits data-hovered/data-pressed on the
   borrowed ToggleButton; we own the look — same ::after recipe as .sd-button. */
.sd-segmented-control__segment::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-segmented-control__segment[data-hovered]::after {
  background: var(--sd-segmented-control-segment-state-hover-current);
}
.sd-segmented-control__segment[data-pressed]::after {
  background: var(--sd-segmented-control-segment-state-pressed-current);
}

/* Raised to `text.DEFAULT` while hovered or pressed: the resting ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-segmented-control__segment[data-hovered]:not([data-selected]),
.sd-segmented-control__segment[data-pressed]:not([data-selected]) {
  color: var(--sd-segmented-control-segment-foreground-hover);
}

.sd-segmented-control__segment[data-selected] {
  color: var(--sd-segmented-control-segment-foreground-selected);
}
/* The pill. Under the content and the state wash (both z-index -1 in the isolated segment, the wash
   later in tree order). It slides because React Aria animates every property it transitions: the
   position is `translate`, and the size is an explicit `width`, a length a transition can reach,
   where the box an inset alone derives could not be interpolated. */
.sd-segmented-control__indicator {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  width: 100%;
  z-index: -1;
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-segmented-control-segment-background-selected);
  box-shadow: var(--sd-segmented-control-segment-shadow);
  pointer-events: none;
  transition:
    translate var(--sd-duration-moderate) var(--sd-easing-standard),
    width var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* outline — the track paints no fill (its border draws the control), and the selected segment takes
   the brand tint and ink with no raised shadow; the leading check below carries the selection too. */
.sd-segmented-control[data-variant="outline"] {
  background: var(--sd-segmented-control-background-outline);
  border-color: var(--sd-segmented-control-border);
}
.sd-segmented-control__indicator[data-variant="outline"] {
  background: var(--sd-segmented-control-segment-background-outline-selected);
  box-shadow: none;
}
.sd-segmented-control__segment[data-variant="outline"][data-selected] {
  color: var(--sd-segmented-control-segment-foreground-outline-selected);
  --sd-segmented-control-segment-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-segmented-control-segment-state-pressed-current: var(--sd-state-pressed-brand-subtle);
}
/* the leading check: reserved at rest so selecting never moves a label, shown on the selected
   segment through the segment's own state relay. */
.sd-segmented-control__segment {
  --sd-segmented-control-check-opacity-current: 0;
}
.sd-segmented-control__segment[data-selected] {
  --sd-segmented-control-check-opacity-current: 1;
}
.sd-segmented-control__check {
  display: inline-flex;
  flex: none;
  margin-inline-end: var(--sd-segmented-control-segment-check-gap);
  color: var(--sd-segmented-control-segment-check-foreground);
  opacity: var(--sd-segmented-control-check-opacity-current);
  transition: opacity var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-segmented-control__check[data-size="x-small"] {
  font-size: var(--sd-segmented-control-segment-check-size-x-small);
}
.sd-segmented-control__check[data-size="small"] {
  font-size: var(--sd-segmented-control-segment-check-size-small);
}
.sd-segmented-control__check[data-size="medium"] {
  font-size: var(--sd-segmented-control-segment-check-size-medium);
}
.sd-segmented-control__check[data-size="large"] {
  font-size: var(--sd-segmented-control-segment-check-size-large);
}
.sd-segmented-control__check[data-size="x-large"] {
  font-size: var(--sd-segmented-control-segment-check-size-x-large);
}

.sd-segmented-control__segment[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-segmented-control__segment[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

@media (prefers-reduced-motion: reduce) {
  .sd-segmented-control__segment,
  .sd-segmented-control__segment::after,
  .sd-segmented-control__indicator {
    transition: none;
  }
}
